import { usePage } from '@inertiajs/react';
import axios from 'axios';
import React, { useEffect, useRef, useState } from 'react';
import Message from './Message';

export default function ChatWindow({
    conversationId,
    participants = [],
    readOnly = false,
}) {
    const { auth } = usePage().props;
    const [messages, setMessages] = useState([]);
    const [newMessage, setNewMessage] = useState('');
    const [attachment, setAttachment] = useState(null);
    const [preview, setPreview] = useState(null);
    const [typingUsers, setTypingUsers] = useState([]);
    const [fetchError, setFetchError] = useState(null);

    const [isConnected, setIsConnected] = useState(true);

    const messagesEndRef = useRef(null);
    const fileInputRef = useRef(null);
    const typingTimeoutsRef = useRef({});

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    useEffect(() => {
        scrollToBottom();
    }, [messages, typingUsers]);

    const markAsRead = () => {
        if (!conversationId) return;
        axios
            .post(`/api/conversations/${conversationId}/read`)
            .catch(console.error);
    };

    const fetchMessages = async () => {
        if (!conversationId) return;
        try {
            const res = await axios.get(
                `/api/conversations/${conversationId}/messages`,
            );
            const newMessages = res.data.data.reverse();
            setMessages(prev => {
                const prevLastId = prev.length > 0 ? prev[prev.length - 1].id : null;
                const newLastId = newMessages.length > 0 ? newMessages[newMessages.length - 1].id : null;
                if (prevLastId !== newLastId || prev.length !== newMessages.length) {
                    return newMessages;
                }
                return prev;
            });
            setFetchError(null);
        } catch (err) {
            console.error('Error fetching messages:', err);
            setFetchError("Failed to load messages. Please try again.");
        }
    };

    // Real-time events connection
    useEffect(() => {
        if (!conversationId) return;

        // Fetch initial messages
        fetchMessages();

        // Subscribe to real-time events
        if (window.Echo) {
            window.Echo.private(`conversation.${conversationId}`)
                .listen('MessageSent', (e) => {
                    setMessages((prev) => {
                        // Prevent duplicates
                        if (prev.find((m) => m.id === e.message.id))
                            return prev;
                        return [...prev, e.message];
                    });

                    // Mark as read if window is focused
                    if (document.hasFocus()) {
                        markAsRead();
                    }
                })
                .listenForWhisper('typing', (e) => {
                    if (e.userId !== auth.user.id) {
                        setTypingUsers((prev) => {
                            if (!prev.includes(e.name)) {
                                return [...prev, e.name];
                            }
                            return prev;
                        });

                        // Clear individual typing indicator after 2 seconds of inactivity
                        if (typingTimeoutsRef.current[e.userId]) {
                            clearTimeout(typingTimeoutsRef.current[e.userId]);
                        }

                        typingTimeoutsRef.current[e.userId] = setTimeout(() => {
                            setTypingUsers((prev) =>
                                prev.filter((name) => name !== e.name),
                            );
                            delete typingTimeoutsRef.current[e.userId];
                        }, 2000);
                    }
                });

            // Connection state monitoring for graceful degradation
            if (window.Echo.connector.pusher) {
                const handleStateChange = (states) => {
                    if (states.current === 'connected') {
                        setIsConnected(true);
                    } else if (states.current === 'disconnected' || states.current === 'unavailable') {
                        setIsConnected(false);
                    }
                };
                window.Echo.connector.pusher.connection.bind('state_change', handleStateChange);
            }
        }

        return () => {
            if (window.Echo) {
                window.Echo.leave(`conversation.${conversationId}`);
                if (window.Echo.connector.pusher) {
                    window.Echo.connector.pusher.connection.unbind('state_change');
                }
            }
            // Clear all typing timeouts
            // eslint-disable-next-line react-hooks/exhaustive-deps
            Object.values(typingTimeoutsRef.current).forEach(clearTimeout);
        };
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [conversationId]);

    // Polling fallback when offline
    useEffect(() => {
        let pollInterval;
        if (!isConnected && conversationId) {
            pollInterval = setInterval(() => {
                fetchMessages();
            }, 5000); // Poll every 5 seconds
        }
        return () => clearInterval(pollInterval);
    }, [isConnected, conversationId]);

    const handleFocus = () => {
        markAsRead();
    };

    const handleTyping = (e) => {
        setNewMessage(e.target.value);

        if (window.Echo && conversationId) {
            window.Echo.private(`conversation.${conversationId}`).whisper(
                'typing',
                {
                    userId: auth.user.id,
                    name: auth.user.name,
                },
            );
        }
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            if (file.size > 5 * 1024 * 1024) {
                alert('File size must be less than 5MB');
                return;
            }
            setAttachment(file);
            setPreview(URL.createObjectURL(file));
        }
    };

    const removeAttachment = () => {
        setAttachment(null);
        setPreview(null);
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    const sendMessage = async (e) => {
        e.preventDefault();
        if (readOnly) return;
        if (!newMessage.trim() && !attachment) return;

        const formData = new FormData();
        if (newMessage.trim()) formData.append('body', newMessage.trim());
        if (attachment) formData.append('attachment', attachment);

        // Optimistic UI update
        const tempMessage = {
            id: Date.now(),
            body: newMessage.trim(),
            sender_id: auth.user.id,
            sender: auth.user,
            created_at: new Date().toISOString(),
            isTemp: true,
            attachments: preview
                ? [
                      {
                          id: Date.now(),
                          type: 'image',
                          path: preview,
                          isTempUrl: true,
                      },
                  ]
                : [],
        };

        setMessages((prev) => [...prev, tempMessage]);
        setNewMessage('');
        removeAttachment();

        try {
            const res = await axios.post(
                `/api/conversations/${conversationId}/messages`,
                formData,
                {
                    headers: { 'Content-Type': 'multipart/form-data' },
                },
            );
            // Replace temp message with real one
            setMessages((prev) =>
                prev.map((m) => (m.id === tempMessage.id ? res.data : m)),
            );
        } catch (error) {
            console.error('Error sending message:', error);
            // Remove temp message on error
            setMessages((prev) => prev.filter((m) => m.id !== tempMessage.id));
            alert('Failed to send message');
        }
    };

    // Derived values for the header
    const otherParticipants = participants.filter((p) => p.id !== auth.user.id);
    const chatTitle =
        otherParticipants.length > 0
            ? otherParticipants.map((p) => p.name).join(', ')
            : `Conversation #${conversationId}`;

    // Calculate unread separator index
    const firstUnreadIndex = messages.findIndex(
        (m) => !m.read && m.sender_id !== auth.user.id,
    );
    const unreadCount =
        firstUnreadIndex !== -1 ? messages.length - firstUnreadIndex : 0;

    return (
        <div
            className="flex h-[600px] flex-col rounded-lg border bg-white shadow-sm"
            onFocus={handleFocus}
            tabIndex="0"
        >
            {/* Header */}
            <div className="flex flex-col border-b bg-gray-50">
                <div className="flex items-center gap-3 p-4">
                    <div className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-full bg-indigo-100 font-bold text-indigo-700">
                        {chatTitle.charAt(0)}
                    </div>
                    <div>
                        <h3 className="font-semibold text-gray-900">{chatTitle}</h3>
                        <p className="text-xs text-gray-500">
                            {readOnly ? 'Read Only' : 'Active'}
                        </p>
                    </div>
                </div>
                {!isConnected && (
                    <div className="bg-yellow-50 px-4 py-1.5 text-xs text-yellow-700 font-medium flex items-center justify-center border-t border-yellow-100">
                        ⚠️ Real-time connection lost. Switched to polling mode. Messages might be delayed.
                    </div>
                )}
            </div>

            {/* Messages Area */}
            <div className="flex flex-1 flex-col overflow-y-auto bg-gray-50 p-4">
                {fetchError ? (
                    <div className="flex flex-1 items-center justify-center text-red-500 font-medium" data-testid="error-message">
                        {fetchError}
                    </div>
                ) : (
                    <>
                        {messages.map((msg, index) => {
                            const showUnreadSeparator = firstUnreadIndex === index;

                            return (
                                <React.Fragment key={msg.id}>
                                    {showUnreadSeparator && (
                                        <div className="flex items-center my-4">
                                            <div className="flex-1 border-t border-red-300"></div>
                                            <span className="px-2 text-xs text-red-500 font-medium">── {unreadCount} new message{unreadCount !== 1 ? 's' : ''} ──</span>
                                            <div className="flex-1 border-t border-red-300"></div>
                                        </div>
                                    )}
                                    <Message
                                        message={msg}
                                        isOwnMessage={msg.sender_id === auth.user.id}
                                    />
                                </React.Fragment>
                            );
                        })}

                        {typingUsers.length > 0 && (
                            <div className="flex items-center gap-2 text-gray-500 text-sm mt-2 ms-10">
                                <span className="italic">{typingUsers.join(', ')} is typing...</span>
                            </div>
                        )}

                        <div ref={messagesEndRef} />
                    </>
                )}
            </div>

            {/* Input Area */}
            <div className="rounded-b-lg border-t bg-white p-4">
                {preview && (
                    <div className="group relative mb-2 inline-block">
                        <img
                            src={preview}
                            alt="Preview"
                            className="h-20 w-20 rounded-md border object-cover"
                        />
                        <button
                            onClick={removeAttachment}
                            className="absolute -top-2 -end-2 flex h-5 w-5 items-center justify-center rounded-full bg-red-500 text-xs text-white opacity-0 transition-opacity group-hover:opacity-100"
                        >
                            &times;
                        </button>
                    </div>
                )}

                <form onSubmit={sendMessage} className="flex items-end gap-2">
                    <input
                        type="file"
                        ref={fileInputRef}
                        onChange={handleFileChange}
                        accept="image/*"
                        className="hidden"
                        disabled={readOnly}
                    />
                    <button
                        type="button"
                        onClick={() => fileInputRef.current?.click()}
                        disabled={readOnly}
                        className="rounded-full p-2 text-gray-500 transition-colors hover:bg-gray-100 hover:text-gray-700 disabled:opacity-50"
                        title={__('general.attach_image')}
                    >
                        <span role="img" aria-label="attachment">
                            📎
                        </span>
                    </button>

                    <textarea
                        value={newMessage}
                        onChange={handleTyping}
                        placeholder={
                            readOnly ? 'Chat is closed' : 'Type a message...'
                        }
                        disabled={readOnly}
                        className="max-h-32 min-h-[44px] flex-1 resize-none rounded-lg border-gray-300 px-3 py-2 focus:border-indigo-500 focus:ring-indigo-500"
                        rows="1"
                        onKeyDown={(e) => {
                            if (e.key === 'Enter' && !e.shiftKey) {
                                e.preventDefault();
                                sendMessage(e);
                            }
                        }}
                    />

                    <button
                        type="submit"
                        disabled={
                            readOnly || (!newMessage.trim() && !attachment)
                        }
                        className="rounded-lg bg-indigo-600 p-2 text-white transition-colors hover:bg-indigo-700 disabled:cursor-not-allowed disabled:opacity-50"
                    >
                        <span role="img" aria-label="send">
                            Send →
                        </span>
                    </button>
                </form>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { router } from '@inertiajs/react';
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from '@/Components/ui/dialog';
import { Button } from '@/Components/ui/button';
import { Input } from '@/Components/ui/input';
import { Label } from '@/Components/ui/label';
import { Textarea } from '@/Components/ui/textarea';
import { __ } from '@/lib/i18n';
import { Sparkles, Loader2, FileText, Plus, Trash2, Send } from 'lucide-react';
import axios from 'axios';

export default function ContractModal({ isOpen, onClose, project, contract, currencies }) {
    const [isLoading, setIsLoading] = useState(false);
    const [isGenerating, setIsGenerating] = useState(false);
    
    const [formData, setFormData] = useState({
        description: '',
        payment_terms: '',
        terms: '',
        notes: '',
        duration: '',
        valid_until: '',
        total_amount: '',
        currency_id: project.client?.currency_id || '',
        key_features: [] as string[],
        pricing_items: [] as any[],
        status: 'draft',
    });

    const [aiPrompt, setAiPrompt] = useState('');
    const [activeTab, setActiveTab] = useState('details'); // details, scope, pricing

    useEffect(() => {
        if (contract) {
            setFormData({
                description: contract.description || '',
                payment_terms: contract.payment_terms || '',
                terms: contract.content?.terms || '',
                notes: contract.content?.notes || '',
                duration: contract.content?.duration || '',
                valid_until: contract.valid_until ? contract.valid_until.split('T')[0] : '',
                total_amount: contract.total_amount || '',
                currency_id: contract.currency_id || '',
                key_features: contract.content?.key_features || [],
                pricing_items: contract.content?.pricing_items || [],
                status: contract.status || 'draft',
            });
        } else {
            setFormData({
                description: '',
                payment_terms: '',
                terms: '',
                notes: '',
                duration: '',
                valid_until: '',
                total_amount: '',
                currency_id: project.client?.currency_id || '',
                key_features: [],
                pricing_items: [],
                status: 'draft',
            });
            setAiPrompt('');
        }
        setActiveTab('details');
    }, [contract, isOpen]);

    const handleGenerateAi = async () => {
        if (!aiPrompt) return alert('Please enter requirements for the AI to generate the contract.');
        setIsGenerating(true);
        try {
            const res = await axios.post('/contracts/ai/generate', {
                project_id: project.id,
                prompt: aiPrompt,
            });
            
            const data = res.data;
            // The AI should return structured data. Merge it into form data.
            setFormData(prev => ({
                ...prev,
                description: data.description || prev.description,
                payment_terms: data.payment_terms || prev.payment_terms,
                terms: data.terms || prev.terms,
                notes: data.notes || prev.notes,
                duration: data.duration || prev.duration,
                key_features: data.key_features || prev.key_features,
                pricing_items: data.pricing_items || prev.pricing_items,
                total_amount: data.total_amount || prev.total_amount,
            }));
            
            setActiveTab('scope');
        } catch (error) {
            console.error('AI Generation Failed:', error);
            alert('Failed to generate contract from AI. Check the console for errors.');
        } finally {
            setIsGenerating(false);
        }
    };

    const handleGenerateInvoice = () => {
        const title = prompt("Enter milestone title:");
        if (!title) return;
        const amount = prompt("Enter amount for this milestone:");
        if (!amount || isNaN(Number(amount))) return alert("Invalid amount");
        
        router.post(route('projects.contracts.invoice', { project: project.id, contract: contract.id }), {
            title,
            amount,
            description: `Milestone for ${project.project_name}`
        }, {
            onSuccess: () => {
                alert("Invoice generated successfully");
            }
        });
    };

    const onSubmit = (e) => {
        e.preventDefault();
        setIsLoading(true);
        
        const routeName = contract 
            ? 'projects.contracts.update' 
            : 'projects.contracts.store';
        
        const params = contract 
            ? { project: project.id, contract: contract.id }
            : { project: project.id };

        const action = contract ? router.put : router.post;

        action(route(routeName, params), formData, {
            onSuccess: () => {
                setIsLoading(false);
                onClose();
            },
            onError: () => {
                setIsLoading(false);
            }
        });
    };

    const addFeature = () => setFormData(p => ({ ...p, key_features: [...p.key_features, ''] }));
    const updateFeature = (i, val) => setFormData(p => {
        const nf = [...p.key_features];
        nf[i] = val;
        return { ...p, key_features: nf };
    });
    const removeFeature = (i) => setFormData(p => ({
        ...p, key_features: p.key_features.filter((_, idx) => idx !== i)
    }));

    const addPricing = () => setFormData(p => ({ 
        ...p, 
        pricing_items: [...p.pricing_items, { item: '', description: '', hours: 0, hourly_rate: 0, total: 0 }] 
    }));
    const updatePricing = (i, field, val) => setFormData(p => {
        const np = [...p.pricing_items];
        np[i][field] = val;
        if (field === 'hours' || field === 'hourly_rate') {
            np[i].total = (np[i].hours || 0) * (np[i].hourly_rate || 0);
        }
        return { ...p, pricing_items: np };
    });
    const removePricing = (i) => setFormData(p => ({
        ...p, pricing_items: p.pricing_items.filter((_, idx) => idx !== i)
    }));

    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>{contract ? 'Edit Contract / Proposal' : 'Create New Contract / Proposal'}</DialogTitle>
                </DialogHeader>
                
                <div className="flex border-b mb-4">
                    <button 
                        className={`px-4 py-2 font-medium text-sm ${activeTab === 'details' ? 'border-b-2 border-indigo-500 text-indigo-600' : 'text-slate-500'}`}
                        onClick={() => setActiveTab('details')}
                    >
                        {__('general.general_details')}</button>
                    <button 
                        className={`px-4 py-2 font-medium text-sm ${activeTab === 'scope' ? 'border-b-2 border-indigo-500 text-indigo-600' : 'text-slate-500'}`}
                        onClick={() => setActiveTab('scope')}
                    >
                        {__('general.scope_features')}</button>
                    <button 
                        className={`px-4 py-2 font-medium text-sm ${activeTab === 'pricing' ? 'border-b-2 border-indigo-500 text-indigo-600' : 'text-slate-500'}`}
                        onClick={() => setActiveTab('pricing')}
                    >
                        {__('general.pricing_milestones')}</button>
                    {contract && (
                        <button 
                            className={`px-4 py-2 font-medium text-sm ${activeTab === 'ai' ? 'border-b-2 border-indigo-500 text-indigo-600' : 'text-slate-500'} ms-auto flex items-center gap-1`}
                            onClick={() => setActiveTab('ai')}
                        >
                            <Sparkles className="w-3 h-3" /> {__('general.ai_assistant')}</button>
                    )}
                </div>

                {!contract && activeTab === 'details' && (
                    <div className="bg-indigo-50 p-4 rounded-lg mb-6 border border-indigo-100 flex flex-col gap-3">
                        <div className="flex items-center gap-2 text-indigo-800 font-semibold">
                            <Sparkles className="w-5 h-5" /> Generate with AI (Recommended)
                        </div>
                        <Textarea 
                            placeholder={__('general.describe_the_project_requirements_featur')} 
                            value={aiPrompt}
                            onChange={(e) => setAiPrompt(e.target.value)}
                            className="bg-white border-indigo-200"
                            rows={3}
                        />
                        <Button 
                            onClick={handleGenerateAi} 
                            disabled={isGenerating} 
                            className="self-end bg-indigo-600 hover:bg-indigo-700 text-white"
                        >
                            {isGenerating ? <><Loader2 className="w-4 h-4 me-2 animate-spin" /> {__('general.generating')}</> : 'Generate Contract'}
                        </Button>
                    </div>
                )}

                <form id="contract-form" onSubmit={onSubmit} className="space-y-6">
                    {activeTab === 'details' && (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="md:col-span-2">
                                <Label>Project Description / Objective</Label>
                                <Textarea 
                                    value={formData.description} 
                                    onChange={e => setFormData({...formData, description: e.target.value})}
                                    rows={4}
                                    placeholder={__('general.executive_summary_of_the_project')}
                                />
                            </div>
                            <div>
                                <Label>{__('general.currency')}</Label>
                                <select 
                                    className="flex h-10 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm ring-offset-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-slate-950 focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                                    value={formData.currency_id}
                                    onChange={e => setFormData({...formData, currency_id: e.target.value})}
                                    required
                                >
                                    <option value="">{__('general.select_currency')}</option>
                                    {currencies.map(c => (
                                        <option key={c.id} value={c.id}>{c.currency} ({c.symbol})</option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <Label>{__('general.total_amount')}</Label>
                                <Input 
                                    type="number" 
                                    step="0.01" 
                                    value={formData.total_amount} 
                                    onChange={e => setFormData({...formData, total_amount: e.target.value})}
                                    required
                                />
                            </div>
                            <div>
                                <Label>Duration (e.g., 3 Months)</Label>
                                <Input 
                                    value={formData.duration} 
                                    onChange={e => setFormData({...formData, duration: e.target.value})}
                                />
                            </div>
                            <div>
                                <Label>{__('general.valid_until')}</Label>
                                <Input 
                                    type="date" 
                                    value={formData.valid_until} 
                                    onChange={e => setFormData({...formData, valid_until: e.target.value})}
                                />
                            </div>
                            {contract && (
                                <div>
                                    <Label>{__('general.contract_status')}</Label>
                                    <select 
                                        className="flex h-10 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm"
                                        value={formData.status}
                                        onChange={e => setFormData({...formData, status: e.target.value})}
                                    >
                                        <option value="draft">{__('general.draft')}</option>
                                        <option value="sent">{__('general.sent')}</option>
                                        <option value="active">{__('general.active')}</option>
                                        <option value="completed">{__('general.completed')}</option>
                                    </select>
                                </div>
                            )}
                        </div>
                    )}

                    {activeTab === 'scope' && (
                        <div className="space-y-4">
                            <div>
                                <div className="flex justify-between items-center mb-2">
                                    <Label className="text-base font-semibold">Key Features / Scope of Work</Label>
                                    <Button type="button" variant="outline" size="sm" onClick={addFeature}>
                                        <Plus className="w-4 h-4 me-1" /> {__('general.add_feature')}</Button>
                                </div>
                                <div className="space-y-2">
                                    {formData.key_features.map((feature, idx) => (
                                        <div key={idx} className="flex items-center gap-2">
                                            <Input 
                                                value={feature} 
                                                onChange={e => updateFeature(idx, e.target.value)} 
                                                placeholder={`Feature ${idx + 1}`}
                                            />
                                            <Button type="button" variant="ghost" size="icon" onClick={() => removeFeature(idx)} className="text-red-500 hover:bg-red-50 hover:text-red-700">
                                                <Trash2 className="w-4 h-4" />
                                            </Button>
                                        </div>
                                    ))}
                                    {formData.key_features.length === 0 && (
                                        <div className="text-center p-4 border border-dashed rounded text-slate-500 text-sm">
                                            No features added. Click "Add Feature" or use AI to generate.
                                        </div>
                                    )}
                                </div>
                            </div>
                            
                            <div className="pt-4 border-t">
                                <Label className="text-base font-semibold block mb-2">{__('general.general_terms_conditions')}</Label>
                                <Textarea 
                                    value={formData.terms} 
                                    onChange={e => setFormData({...formData, terms: e.target.value})}
                                    rows={6}
                                    placeholder={__('general.legal_terms_responsibilities_etc')}
                                />
                            </div>
                        </div>
                    )}

                    {activeTab === 'pricing' && (
                        <div className="space-y-4">
                            <div>
                                <div className="flex justify-between items-center mb-2">
                                    <Label className="text-base font-semibold">Pricing Items (Quotation)</Label>
                                    <Button type="button" variant="outline" size="sm" onClick={addPricing}>
                                        <Plus className="w-4 h-4 me-1" /> {__('general.add_item')}</Button>
                                </div>
                                <div className="space-y-3">
                                    {formData.pricing_items.map((item, idx) => (
                                        <div key={idx} className="flex items-start gap-2 bg-slate-50 p-3 rounded border">
                                            <div className="grid grid-cols-1 md:grid-cols-4 gap-2 flex-1">
                                                <div className="md:col-span-4">
                                                    <Input placeholder={__('general.item_title')} value={item.item} onChange={e => updatePricing(idx, 'item', e.target.value)} />
                                                </div>
                                                <div className="md:col-span-4">
                                                    <Input placeholder={__('general.description')} value={item.description} onChange={e => updatePricing(idx, 'description', e.target.value)} />
                                                </div>
                                                <div>
                                                    <Label className="text-xs">Hours/Qty</Label>
                                                    <Input type="number" placeholder={__('general.hours')} value={item.hours} onChange={e => updatePricing(idx, 'hours', e.target.value)} />
                                                </div>
                                                <div>
                                                    <Label className="text-xs">{__('general.rate')}</Label>
                                                    <Input type="number" placeholder={__('general.rate')} value={item.hourly_rate} onChange={e => updatePricing(idx, 'hourly_rate', e.target.value)} />
                                                </div>
                                                <div className="md:col-span-2">
                                                    <Label className="text-xs">{__('general.line_total')}</Label>
                                                    <Input type="number" disabled value={item.total} className="bg-slate-100" />
                                                </div>
                                            </div>
                                            <Button type="button" variant="ghost" size="icon" onClick={() => removePricing(idx)} className="text-red-500 mt-6">
                                                <Trash2 className="w-4 h-4" />
                                            </Button>
                                        </div>
                                    ))}
                                    {formData.pricing_items.length === 0 && (
                                        <div className="text-center p-4 border border-dashed rounded text-slate-500 text-sm">
                                            {__('general.no_pricing_items_added')}</div>
                                    )}
                                </div>
                            </div>
                            
                            <div className="pt-4 border-t">
                                <Label className="text-base font-semibold block mb-2">Payment Terms (Milestones)</Label>
                                <Textarea 
                                    value={formData.payment_terms} 
                                    onChange={e => setFormData({...formData, payment_terms: e.target.value})}
                                    rows={4}
                                    placeholder="e.g. 50% upfront, 25% after UI, 25% upon delivery..."
                                />
                            </div>

                            {contract && (
                                <div className="pt-4 border-t flex items-center justify-between">
                                    <div className="text-sm text-slate-600">
                                        {__('general.you_can_generate_invoices_dynamically_fr')}</div>
                                    <Button type="button" variant="outline" onClick={handleGenerateInvoice}>
                                        <Send className="w-4 h-4 me-2" /> {__('general.generate_invoice')}</Button>
                                </div>
                            )}
                        </div>
                    )}
                    
                    {activeTab === 'ai' && contract && (
                        <div className="bg-indigo-50 p-4 rounded-lg mb-6 border border-indigo-100 flex flex-col gap-3">
                            <div className="flex items-center gap-2 text-indigo-800 font-semibold">
                                <Sparkles className="w-5 h-5" /> {__('general.refine_with_ai')}</div>
                            <p className="text-sm text-indigo-700 mb-2">
                                Describe the changes you want to make to this contract (e.g., "Add a milestone for testing", "Change the duration to 6 months and adjust pricing accordingly"). The AI will create a new version.
                            </p>
                            <Textarea 
                                placeholder={__('general.instructions_for_ai')} 
                                value={aiPrompt}
                                onChange={(e) => setAiPrompt(e.target.value)}
                                className="bg-white border-indigo-200"
                                rows={3}
                            />
                            <Button 
                                onClick={handleGenerateAi} 
                                disabled={isGenerating} 
                                className="self-end bg-indigo-600 hover:bg-indigo-700 text-white"
                            >
                                {isGenerating ? <><Loader2 className="w-4 h-4 me-2 animate-spin" /> {__('general.processing')}</> : 'Refine Contract'}
                            </Button>
                        </div>
                    )}

                </form>

                <DialogFooter className="mt-6 border-t pt-4">
                    <Button variant="outline" onClick={onClose} type="button">{__('general.cancel')}</Button>
                    <Button type="submit" form="contract-form" disabled={isLoading || isGenerating}>
                        {isLoading ? <Loader2 className="w-4 h-4 animate-spin me-2" /> : null}
                        {contract ? 'Update Contract (Creates new version)' : 'Create Contract'}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState } from 'react';
import { Head, Link, useForm, router } from '@inertiajs/react';
import AdminSidebarLayout from '@/Layouts/AdminSidebarLayout';
import { Users, Save, ChevronLeft, ArrowLeft } from 'lucide-react';
import { Button } from '@/Components/ui/button';
import { __ } from '@/lib/i18n';

export default function LegacyCoWorkerEdit({ worker, techTags = [] }) {
    const { data, setData, put, processing, errors } = useForm({
        person_name: worker.person_name || '',
        email: worker.email || '',
        mobile: worker.mobile || '',
        facebook: worker.facebook || '',
        linked_in: worker.linked_in || '',
        whatsapp: worker.whatsapp || '',
        time_from: worker.time_from || '',
        time_to: worker.time_to || '',
        selectedTechTags: worker.tech_tags ? worker.tech_tags.map(t => t.id) : [],
    });

    const submit = (e) => {
        e.preventDefault();
        put(`/admin/users/legacy-coworker/${worker.id}`);
    };

    const handleTagToggle = (tagId) => {
        if (data.selectedTechTags.includes(tagId)) {
            setData('selectedTechTags', data.selectedTechTags.filter(id => id !== tagId));
        } else {
            setData('selectedTechTags', [...data.selectedTechTags, tagId]);
        }
    };

    return (
        <AdminSidebarLayout title={`Edit ${worker.person_name}`} header="Edit Co-Worker">
            <Head title={`Edit ${worker.person_name}`} />

            <div className="mb-6 flex items-center gap-4">
                <Link
                    href={`/admin/users/legacy-coworker/${worker.id}`}
                    className="inline-flex items-center justify-center w-10 h-10 rounded-full bg-white border border-slate-200 text-slate-500 hover:text-slate-700 hover:bg-slate-50 transition-colors"
                >
                    <ArrowLeft className="w-5 h-5" />
                </Link>
                <div>
                    <h1 className="text-2xl font-bold text-slate-900 flex items-center gap-2">{__('general.edit_legacy_co_worker')}</h1>
                    <p className="text-sm text-slate-500">{__('general.update_coworker_contact_availability_and_skills')}</p>
                </div>
            </div>

            <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                <form onSubmit={submit} className="p-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        
                        {/* Basic Info */}
                        <div className="space-y-4">
                            <h2 className="text-lg font-semibold text-slate-800">{__('general.basic_information')}</h2>
                            
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">{__('general.full_name')}</label>
                                <Input
                                    type="text"
                                    value={data.person_name}
                                    onChange={e => setData('person_name', e.target.value)}
                                    className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:ring-2 focus:ring-slate-800 focus:border-slate-800"
                                />
                                {errors.person_name && <p className="text-red-500 text-xs mt-1">{errors.person_name}</p>}
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">{__('general.email_address')}</label>
                                <Input
                                    type="email"
                                    value={data.email}
                                    onChange={e => setData('email', e.target.value)}
                                    className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:ring-2 focus:ring-slate-800 focus:border-slate-800"
                                />
                                {errors.email && <p className="text-red-500 text-xs mt-1">{errors.email}</p>}
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">{__('general.mobile_number')}</label>
                                <Input
                                    type="text"
                                    value={data.mobile}
                                    onChange={e => setData('mobile', e.target.value)}
                                    className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:ring-2 focus:ring-slate-800 focus:border-slate-800"
                                />
                                {errors.mobile && <p className="text-red-500 text-xs mt-1">{errors.mobile}</p>}
                            </div>
                            
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">{__('general.whatsapp')}</label>
                                <Input
                                    type="text"
                                    value={data.whatsapp}
                                    onChange={e => setData('whatsapp', e.target.value)}
                                    placeholder="+20 101 521 8548"
                                    className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:ring-2 focus:ring-slate-800 focus:border-slate-800"
                                />
                                {errors.whatsapp && <p className="text-red-500 text-xs mt-1">{errors.whatsapp}</p>}
                            </div>
                        </div>

                        {/* Social & Availability */}
                        <div className="space-y-4">
                            <h2 className="text-lg font-semibold text-slate-800">{__('general.social_availability')}</h2>
                            
                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">{__('general.facebook_url')}</label>
                                <Input
                                    type="url"
                                    value={data.facebook}
                                    onChange={e => setData('facebook', e.target.value)}
                                    className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:ring-2 focus:ring-slate-800 focus:border-slate-800"
                                />
                                {errors.facebook && <p className="text-red-500 text-xs mt-1">{errors.facebook}</p>}
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-700 mb-1">{__('general.linkedin_url')}</label>
                                <Input
                                    type="url"
                                    value={data.linked_in}
                                    onChange={e => setData('linked_in', e.target.value)}
                                    className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:ring-2 focus:ring-slate-800 focus:border-slate-800"
                                />
                                {errors.linked_in && <p className="text-red-500 text-xs mt-1">{errors.linked_in}</p>}
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 mb-1">{__('general.available_from')}</label>
                                    <Input
                                        type="time"
                                        value={data.time_from}
                                        onChange={e => setData('time_from', e.target.value)}
                                        className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:ring-2 focus:ring-slate-800 focus:border-slate-800"
                                    />
                                    {errors.time_from && <p className="text-red-500 text-xs mt-1">{errors.time_from}</p>}
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 mb-1">{__('general.available_to')}</label>
                                    <Input
                                        type="time"
                                        value={data.time_to}
                                        onChange={e => setData('time_to', e.target.value)}
                                        className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:ring-2 focus:ring-slate-800 focus:border-slate-800"
                                    />
                                    {errors.time_to && <p className="text-red-500 text-xs mt-1">{errors.time_to}</p>}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Tech Tags */}
                    <div className="mt-8">
                        <h2 className="text-lg font-semibold text-slate-800 mb-3">{__('general.programming_technologies')}</h2>
                        <div className="flex flex-wrap gap-2">
                            {techTags.map(tag => (
                                <Button
                                    key={tag.id}
                                    type="button"
                                    onClick={() => handleTagToggle(tag.id)}
                                    className={`px-3 py-1.5 rounded-full text-sm font-medium border transition-colors ${
                                        data.selectedTechTags.includes(tag.id)
                                            ? 'bg-indigo-100 text-slate-900 border-indigo-200'
                                            : 'bg-white text-slate-600 border-slate-200 hover:border-slate-300 hover:bg-slate-50'
                                    }`}
                                >
                                    {tag.name}
                                </Button>
                            ))}
                        </div>
                        {errors.selectedTechTags && <p className="text-red-500 text-xs mt-2">{errors.selectedTechTags}</p>}
                    </div>

                    <div className="mt-8 flex justify-end gap-3 pt-6 border-t border-slate-100">
                        <Link
                            href={`/admin/users/legacy-coworker/${worker.id}`}
                            className="px-4 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-300 rounded-md shadow-sm hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-slate-800"
                        >
                            {__('general.cancel')}</Link>
                        <Button type="submit" disabled={processing} className="flex items-center gap-2">
                            <Save className="w-4 h-4" />{__('general.save_changes')}</Button>
                    </div>
                </form>
            </div>
        </AdminSidebarLayout>
    );
}

import React, { useState, useCallback } from 'react';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout';
import { Head, useForm, router } from '@inertiajs/react';
import { ShieldCheck, UploadCloud, FileText, CheckCircle2, AlertCircle, XCircle, Trash2, Download, ArrowRight, ArrowLeft, Image as ImageIcon } from 'lucide-react';
import { Button } from '@/Components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle, CardFooter } from '@/Components/ui/card';
import { useToast } from '@/Components/ui/use-toast';
import { Badge } from '@/Components/ui/badge';
import { useDropzone } from 'react-dropzone';
import { motion, AnimatePresence } from 'framer-motion';
import { __ } from '@/lib/i18n';

interface DocumentType {
    id: number;
    document_type: string;
    original_filename: string;
    file_size: number;
    status: string;
    rejection_reason?: string;
    created_at: string;
}

interface KycStatus {
    isVerified: boolean;
    verifiedAt: string | null;
    provider: string | null;
    notes: string | null;
}

interface Props {
    auth: { user: any };
    kycStatus: KycStatus;
    documents: DocumentType[];
    missingDocs: string[];
    requiredDocs: string[];
}

const STEPS = [
    { id: 'id_front', label: 'Government ID', desc: 'Front of your Passport or National ID', required: true },
    { id: 'selfie', label: 'Selfie Verification', desc: 'A clear photo of your face holding your ID', required: true },
    { id: 'proof_of_address', label: 'Proof of Address', desc: 'Utility bill or bank statement (Optional)', required: false }
];

export default function KycIndex({ auth, kycStatus, documents, missingDocs, requiredDocs }: Props) {
    const { toast } = useToast();
    const [activeStep, setActiveStep] = useState(0);
    const [uploadingType, setUploadingType] = useState<string | null>(null);

    const { data, setData, post, processing, errors, reset } = useForm({
        document_type: '',
        document: null as File | null,
    });

    const isVerified = kycStatus.isVerified;
    const isPendingReview = !isVerified && kycStatus.notes?.includes('submitted');
    const isRejected = !isVerified && kycStatus.notes?.includes('rejected');
    const canSubmit = missingDocs.length === 0 && !isVerified && !isPendingReview;

    const onDrop = useCallback((acceptedFiles: File[], docType: string) => {
        const file = acceptedFiles[0];
        if (file) {
            if (file.size > 5 * 1024 * 1024) {
                toast({ title: "File too large", description: "Maximum file size is 5MB.", variant: "destructive" });
                return;
            }
            setData({ document_type: docType, document: file });
            setUploadingType(docType);
        }
    }, [setData, toast]);

    const handleUpload = (docType: string) => {
        post(route('kyc.upload'), {
            preserveScroll: true,
            onSuccess: () => {
                toast({ title: "Uploaded", description: "Document uploaded successfully." });
                reset();
                setUploadingType(null);
                if (activeStep < STEPS.length - 1) {
                    setActiveStep(prev => prev + 1);
                }
            },
            onError: () => {
                setUploadingType(null);
            }
        });
    };

    const handleSubmitForReview = () => {
        router.post(route('kyc.submit'), {}, {
            preserveScroll: true,
            onSuccess: () => {
                toast({ title: "Submitted", description: "Your KYC application is now under review." });
            }
        });
    };

    const handleDelete = (id: number) => {
        if (confirm("Are you sure you want to delete this document?")) {
            router.delete(route('kyc.delete', id), {
                preserveScroll: true,
                onSuccess: () => toast({ title: "Deleted", description: "Document removed." })
            });
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'approved': return 'bg-emerald-50 text-emerald-700 border-emerald-200';
            case 'rejected': return 'bg-rose-50 text-rose-700 border-rose-200';
            default: return 'bg-amber-50 text-amber-700 border-amber-200';
        }
    };

    const renderDropzone = (docDef: any) => {
        const { getRootProps, getInputProps, isDragActive } = useDropzone({
            onDrop: (files) => onDrop(files, docDef.id),
            accept: {
                'image/jpeg': [],
                'image/png': [],
                'application/pdf': []
            },
            maxSize: 5242880, // 5MB
            multiple: false
        });

        const uploadedDoc = documents.find(d => d.document_type === docDef.id);
        const isCurrentUploading = data.document && data.document_type === docDef.id;

        if (uploadedDoc) {
            return (
                <div className="flex flex-col items-center justify-center p-8 bg-slate-50 border-2 border-dashed border-slate-200 rounded-xl">
                    <CheckCircle2 className="w-12 h-12 text-emerald-500 mb-3" />
                    <h4 className="text-sm font-semibold text-slate-900">{uploadedDoc.original_filename}</h4>
                    <p className="text-xs text-slate-500 mt-1 mb-4">{__('general.uploaded_successfully')}</p>
                    <div className="flex gap-2">
                        <Button variant="outline" size="sm" asChild>
                            <a href={route('kyc.download', uploadedDoc.id)} target="_blank" rel="noreferrer">
                                <Download className="w-4 h-4 me-2" /> {__('general.view')}</a>
                        </Button>
                        {!isPendingReview && uploadedDoc.status !== 'approved' && (
                            <Button variant="destructive" size="sm" onClick={() => handleDelete(uploadedDoc.id)}>
                                <Trash2 className="w-4 h-4 me-2" /> {__('general.remove')}</Button>
                        )}
                    </div>
                </div>
            );
        }

        return (
            <div className="space-y-4">
                <div 
                    {...getRootProps()} 
                    className={`flex flex-col items-center justify-center p-8 border-2 border-dashed rounded-xl cursor-pointer transition-colors ${
                        isDragActive ? 'border-indigo-500 bg-indigo-50' : 'border-slate-300 bg-slate-50 hover:bg-slate-100 hover:border-slate-400'
                    }`}
                >
                    <input {...getInputProps()} />
                    <div className="w-12 h-12 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center mb-4">
                        <UploadCloud className="w-6 h-6" />
                    </div>
                    {isCurrentUploading ? (
                        <div className="text-center">
                            <p className="text-sm font-semibold text-slate-900">{data.document?.name}</p>
                            <p className="text-xs text-slate-500 mt-1">{__('general.ready_to_upload')}</p>
                        </div>
                    ) : (
                        <div className="text-center">
                            <p className="text-sm font-semibold text-slate-900">{__('general.drag_drop_your_file_here')}</p>
                            <p className="text-xs text-slate-500 mt-1">or click to browse from your device</p>
                            <p className="text-xs text-slate-400 mt-2">{__('general.jpg_png_pdf_up_to_5mb')}</p>
                        </div>
                    )}
                </div>
                
                {isCurrentUploading && (
                    <div className="flex justify-end">
                        <Button 
                            onClick={() => handleUpload(docDef.id)} 
                            disabled={processing}
                            className="bg-indigo-600 hover:bg-indigo-700 text-white shadow-md"
                        >
                            {processing ? 'Uploading...' : 'Confirm Upload'}
                        </Button>
                    </div>
                )}
                {errors.document && uploadingType === docDef.id && (
                    <p className="text-rose-500 text-xs mt-2">{errors.document}</p>
                )}
            </div>
        );
    };

    return (
        <AuthenticatedLayout header={<h2 className="font-semibold text-xl text-foreground leading-tight">{__('general.identity_verification')}</h2>}>
            <Head title={__('general.kyc_verification')} />

            <div className="max-w-4xl mx-auto py-10 px-4 sm:px-6 lg:px-8 space-y-8">
                {/* STATUS BANNER */}
                <div className={`p-6 rounded-2xl border shadow-sm ${
                    isVerified ? 'bg-emerald-50 border-emerald-200' :
                    isPendingReview ? 'bg-amber-50 border-amber-200' :
                    isRejected ? 'bg-rose-50 border-rose-200' :
                    'bg-slate-50 border-slate-200'
                }`}>
                    <div className="flex items-start gap-4">
                        <div className={`p-3 rounded-full ${
                            isVerified ? 'bg-emerald-100 text-emerald-600' :
                            isPendingReview ? 'bg-amber-100 text-amber-600' :
                            isRejected ? 'bg-rose-100 text-rose-600' :
                            'bg-slate-200 text-slate-600'
                        }`}>
                            {isVerified ? <CheckCircle2 className="w-6 h-6" /> :
                             isPendingReview ? <AlertCircle className="w-6 h-6" /> :
                             isRejected ? <XCircle className="w-6 h-6" /> :
                             <ShieldCheck className="w-6 h-6" />}
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-slate-900 mb-1">
                                {isVerified ? 'Identity Verified' :
                                 isPendingReview ? 'Application Under Review' :
                                 isRejected ? 'Application Rejected' :
                                 'Verification Required'}
                            </h3>
                            <p className="text-sm text-slate-600">
                                {isVerified ? 'Your identity has been fully verified. You have full access to all features.' :
                                 isPendingReview ? 'We are reviewing your documents. This usually takes 1-2 business days.' :
                                 isRejected ? `Your application was rejected. Reason: ${kycStatus.notes?.replace('KYC rejected: ', '')}` :
                                 'To comply with regulations and enable full features, please verify your identity.'}
                            </p>
                        </div>
                    </div>
                </div>

                {!isVerified && !isPendingReview && (
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                        {/* WIZARD SIDEBAR */}
                        <div className="md:col-span-1 space-y-6">
                            <div className="space-y-4">
                                <h3 className="text-lg font-bold text-slate-900">{__('general.verification_steps')}</h3>
                                <div className="space-y-3 relative">
                                    <div className="absolute left-[15px] top-4 bottom-4 w-0.5 bg-slate-200" />
                                    {STEPS.map((step, idx) => {
                                        const isCompleted = documents.some(d => d.document_type === step.id);
                                        const isActive = idx === activeStep;
                                        return (
                                            <div 
                                                key={step.id} 
                                                className={`relative flex items-center gap-4 p-3 rounded-xl cursor-pointer transition-colors ${isActive ? 'bg-indigo-50 border border-indigo-100 shadow-sm' : 'hover:bg-slate-50'}`}
                                                onClick={() => setActiveStep(idx)}
                                            >
                                                <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 relative z-10 ${
                                                    isCompleted ? 'bg-emerald-500 text-white shadow-md' :
                                                    isActive ? 'bg-indigo-600 text-white shadow-md ring-4 ring-indigo-100' :
                                                    'bg-slate-200 text-slate-500 border-2 border-white'
                                                }`}>
                                                    {isCompleted ? <CheckCircle2 className="w-4 h-4" /> : <span className="text-sm font-bold">{idx + 1}</span>}
                                                </div>
                                                <div>
                                                    <p className={`text-sm font-semibold ${isActive ? 'text-indigo-900' : 'text-slate-700'}`}>{step.label}</p>
                                                    {step.required && <span className="text-[10px] uppercase font-bold text-rose-500 tracking-wider">{__('general.required')}</span>}
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                            
                            <div className="bg-slate-50 p-5 rounded-xl border border-slate-100">
                                <h4 className="font-semibold text-slate-900 text-sm flex items-center gap-2 mb-2">
                                    <ShieldCheck className="w-4 h-4 text-indigo-500"/>
                                    {__('general.bankgrade_security')}</h4>
                                <p className="text-xs text-slate-600 leading-relaxed">
                                    {__('general.your_documents_are_encrypted_and_stored')}</p>
                            </div>
                        </div>

                        {/* WIZARD CONTENT */}
                        <div className="md:col-span-2">
                            <Card className="shadow-lg border-slate-200">
                                <AnimatePresence mode="wait">
                                    <motion.div
                                        key={activeStep}
                                        initial={{ opacity: 0, y: 10 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        exit={{ opacity: 0, y: -10 }}
                                        transition={{ duration: 0.2 }}
                                    >
                                        <CardHeader>
                                            <div className="flex items-center justify-between">
                                                <div>
                                                    <CardTitle>{STEPS[activeStep].label}</CardTitle>
                                                    <CardDescription className="mt-1">{STEPS[activeStep].desc}</CardDescription>
                                                </div>
                                                <ImageIcon className="w-8 h-8 text-slate-300" />
                                            </div>
                                        </CardHeader>
                                        <CardContent>
                                            {renderDropzone(STEPS[activeStep])}
                                        </CardContent>
                                        <CardFooter className="bg-slate-50 border-t flex justify-between p-6">
                                            <Button 
                                                variant="outline" 
                                                onClick={() => setActiveStep(prev => Math.max(0, prev - 1))}
                                                disabled={activeStep === 0}
                                            >
                                                <ArrowLeft className="w-4 h-4 me-2" /> {__('general.back')}</Button>
                                            
                                            {activeStep < STEPS.length - 1 ? (
                                                <Button onClick={() => setActiveStep(prev => prev + 1)}>
                                                    {__('general.next')}<ArrowRight className="w-4 h-4 ms-2" />
                                                </Button>
                                            ) : (
                                                <Button 
                                                    onClick={handleSubmitForReview} 
                                                    disabled={!canSubmit}
                                                    className={canSubmit ? 'bg-emerald-600 hover:bg-emerald-700 text-white' : ''}
                                                >
                                                    <CheckCircle2 className="w-4 h-4 me-2" /> {__('general.submit_application')}</Button>
                                            )}
                                        </CardFooter>
                                    </motion.div>
                                </AnimatePresence>
                            </Card>
                        </div>
                    </div>
                )}
                
                {isPendingReview && (
                    <div className="text-center p-12 bg-white rounded-2xl border border-slate-200 shadow-sm">
                        <div className="w-20 h-20 bg-indigo-50 rounded-full flex items-center justify-center mx-auto mb-6">
                            <CheckCircle2 className="w-10 h-10 text-indigo-500" />
                        </div>
                        <h2 className="text-2xl font-bold text-slate-900 mb-2">{__('general.application_received')}</h2>
                        <p className="text-slate-600 max-w-md mx-auto">
                            {__('general.thank_you_for_submitting_your_documents')}</p>
                    </div>
                )}
            </div>
        </AuthenticatedLayout>
    );
}

import React, { useState, useEffect, useRef } from 'react';
import { Head } from '@inertiajs/react';
import WebToolsLayout from '@/Layouts/WebToolsLayout';
import { Card, CardContent, CardHeader, CardTitle } from '@/Components/ui/card';
import { Button } from '@/Components/ui/button';
import { Input } from '@/Components/ui/input';
import { Plus, Play, Pause, RotateCcw, X, Timer, Info } from 'lucide-react';
import { useToast } from '@/Components/ui/use-toast';
import { __ } from '@/lib/i18n';

interface TimerData {
    id: string;
    label: string;
    hours: number;
    minutes: number;
    seconds: number;
    totalSeconds: number;
    remainingSeconds: number;
    isRunning: boolean;
}

export default function MultipleCountdownTimer() {
    const { toast } = useToast();
    const [newLabel, setNewLabel] = useState('');
    const [timers, setTimers] = useState<TimerData[]>([]);
    
    // We use a ref to hold an audio element so we don't trigger re-renders
    const audioRef = useRef<HTMLAudioElement | null>(null);

    useEffect(() => {
        audioRef.current = new Audio('/sounds/mixkit-short-rooster-crowing-2470.wav');
        
        // Add a default timer
        addTimer('Timer 1');
    }, []);

    // Main interval to tick timers
    useEffect(() => {
        const interval = setInterval(() => {
            setTimers(prev => prev.map(timer => {
                if (timer.isRunning && timer.remainingSeconds > 0) {
                    const nextRemaining = timer.remainingSeconds - 1;
                    
                    if (nextRemaining <= 0) {
                        // Timer finished
                        if (audioRef.current) {
                            audioRef.current.play().catch(e => console.error("Audio playback failed:", e));
                        }
                        toast({ title: 'Timer Finished!', description: `"${timer.label}" has reached zero.` });
                        return { ...timer, remainingSeconds: 0, isRunning: false };
                    }
                    
                    return { ...timer, remainingSeconds: nextRemaining };
                }
                return timer;
            }));
        }, 1000);

        return () => clearInterval(interval);
    }, [toast]);

    const addTimer = (label?: string) => {
        const defaultLabel = label || `Timer ${timers.length + 1}`;
        const newTimer: TimerData = {
            id: Math.random().toString(36).substring(2, 9),
            label: defaultLabel,
            hours: 0,
            minutes: 0,
            seconds: 0,
            totalSeconds: 0,
            remainingSeconds: 0,
            isRunning: false
        };
        setTimers(prev => [...prev, newTimer]);
    };

    const handleAddClick = () => {
        addTimer(newLabel.trim());
        setNewLabel('');
    };

    const removeTimer = (id: string) => {
        setTimers(prev => prev.filter(t => t.id !== id));
    };

    const updateTimerInput = (id: string, field: 'hours' | 'minutes' | 'seconds', value: number) => {
        setTimers(prev => prev.map(t => {
            if (t.id === id) {
                return { ...t, [field]: value };
            }
            return t;
        }));
    };

    const startTimer = (id: string) => {
        setTimers(prev => prev.map(t => {
            if (t.id === id) {
                let total = t.totalSeconds;
                let remaining = t.remainingSeconds;
                
                // If it's starting fresh or was reset (0 remaining and not running)
                if (t.remainingSeconds === 0 && t.totalSeconds === 0) {
                    total = (t.hours * 3600) + (t.minutes * 60) + t.seconds;
                    remaining = total;
                } else if (t.remainingSeconds === 0) {
                     // Restarting from previous inputs after finishing
                     total = (t.hours * 3600) + (t.minutes * 60) + t.seconds;
                     remaining = total;
                }
                
                if (remaining > 0) {
                    return { ...t, totalSeconds: total, remainingSeconds: remaining, isRunning: true };
                }
            }
            return t;
        }));
    };

    const pauseTimer = (id: string) => {
        setTimers(prev => prev.map(t => t.id === id ? { ...t, isRunning: false } : t));
    };

    const resetTimer = (id: string) => {
        setTimers(prev => prev.map(t => t.id === id ? { ...t, isRunning: false, remainingSeconds: 0, totalSeconds: 0 } : t));
    };

    const formatTime = (seconds: number) => {
        const h = Math.floor(seconds / 3600).toString().padStart(2, '0');
        const m = Math.floor((seconds % 3600) / 60).toString().padStart(2, '0');
        const s = (seconds % 60).toString().padStart(2, '0');
        return `${h}:${m}:${s}`;
    };

    return (
        <WebToolsLayout title={__('general.multiple_countdown_timer')} activeNav="explore">
            <div className="max-w-6xl mx-auto py-12 px-4 sm:px-6">
                <div className="text-center mb-10">
                    <div className="inline-flex items-center justify-center p-3 bg-indigo-100 text-indigo-700 rounded-2xl mb-4">
                        <Timer className="w-8 h-8" />
                    </div>
                    <h1 className="text-3xl font-extrabold text-slate-900 sm:text-4xl">{__('general.multiple_countdown_timer')}</h1>
                    <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">
                        {__('general.create_and_manage_multiple_timers_simult')}</p>
                </div>

                <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 mb-8 max-w-2xl mx-auto">
                    <div className="flex gap-3">
                        <Input 
                            placeholder="Timer Label (e.g., 'Boil Eggs')" 
                            value={newLabel}
                            onChange={(e) => setNewLabel(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleAddClick()}
                            className="flex-1"
                        />
                        <Button onClick={handleAddClick} className="gap-2">
                            <Plus className="w-4 h-4" />
                            {__('general.add_timer')}</Button>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 mb-10">
                    {timers.map(timer => {
                        const progress = timer.totalSeconds > 0 
                            ? ((timer.totalSeconds - timer.remainingSeconds) / timer.totalSeconds) * 100 
                            : 0;
                            
                        const isFinished = timer.totalSeconds > 0 && timer.remainingSeconds === 0 && !timer.isRunning;

                        return (
                            <Card key={timer.id} className={`shadow-sm transition-colors border-2 ${isFinished ? 'border-red-400 bg-red-50' : timer.isRunning ? 'border-indigo-400 bg-indigo-50/30' : 'border-slate-200'}`}>
                                <CardHeader className="pb-2 pt-4 px-4 flex flex-row items-center justify-between space-y-0">
                                    <CardTitle className="text-base font-semibold truncate pe-4 text-slate-800" title={timer.label}>
                                        {timer.label}
                                    </CardTitle>
                                    <Button variant="ghost" size="icon" className="h-6 w-6 text-slate-400 hover:text-red-500 shrink-0" onClick={() => removeTimer(timer.id)}>
                                        <X className="h-4 w-4" />
                                    </Button>
                                </CardHeader>
                                <CardContent className="px-4 pb-4">
                                    <div className="text-center mb-4">
                                        <div className={`text-5xl font-mono tracking-wider font-bold mb-4 ${isFinished ? 'text-red-600 animate-pulse' : 'text-slate-900'}`}>
                                            {formatTime(timer.remainingSeconds)}
                                        </div>
                                        
                                        {!timer.isRunning && timer.remainingSeconds === 0 && (
                                            <div className="flex items-center justify-center gap-2 mb-4">
                                                <Input 
                                                    type="number" min={0} max={99} 
                                                    className="w-16 text-center text-lg h-10" 
                                                    placeholder="00" 
                                                    value={timer.hours || ''} 
                                                    onChange={e => updateTimerInput(timer.id, 'hours', parseInt(e.target.value) || 0)} 
                                                />
                                                <span className="font-bold text-slate-400">:</span>
                                                <Input 
                                                    type="number" min={0} max={59} 
                                                    className="w-16 text-center text-lg h-10" 
                                                    placeholder="00" 
                                                    value={timer.minutes || ''} 
                                                    onChange={e => updateTimerInput(timer.id, 'minutes', parseInt(e.target.value) || 0)} 
                                                />
                                                <span className="font-bold text-slate-400">:</span>
                                                <Input 
                                                    type="number" min={0} max={59} 
                                                    className="w-16 text-center text-lg h-10" 
                                                    placeholder="00" 
                                                    value={timer.seconds || ''} 
                                                    onChange={e => updateTimerInput(timer.id, 'seconds', parseInt(e.target.value) || 0)} 
                                                />
                                            </div>
                                        )}
                                    </div>

                                    <div className="flex justify-center gap-2 mb-4">
                                        {!timer.isRunning ? (
                                            <Button size="icon" variant="default" className="h-10 w-10 bg-emerald-600 hover:bg-emerald-700" onClick={() => startTimer(timer.id)}>
                                                <Play className="h-5 w-5 ms-1" />
                                            </Button>
                                        ) : (
                                            <Button size="icon" variant="destructive" className="h-10 w-10 text-white" onClick={() => pauseTimer(timer.id)}>
                                                <Pause className="h-5 w-5" />
                                            </Button>
                                        )}
                                        <Button size="icon" variant="secondary" className="h-10 w-10" onClick={() => resetTimer(timer.id)}>
                                            <RotateCcw className="h-4 w-4" />
                                        </Button>
                                    </div>

                                    <div className="h-1.5 bg-slate-100 rounded-full overflow-hidden"><div className="h-full bg-slate-900 transition-all duration-1000" style={{ width: `${progress}%` }} /></div>
                                </CardContent>
                            </Card>
                        );
                    })}
                </div>

                {timers.length === 0 && (
                    <div className="text-center py-12 text-slate-500">
                        {__('general.no_timers_added_yet_use_the_input_above')}</div>
                )}

                <div className="max-w-2xl mx-auto">
                    <Card className="bg-slate-50 border-slate-200">
                        <CardHeader className="pb-3">
                            <CardTitle className="text-base flex items-center gap-2 text-slate-700">
                                <Info className="w-4 h-4" />
                                {__('general.how_to_use')}</CardTitle>
                        </CardHeader>
                        <CardContent className="text-sm text-slate-600">
                            <ul className="list-disc ps-5 space-y-2">
                                <li><strong>Add a Timer:</strong> Enter a label (optional) and click "Add Timer".</li>
                                <li><strong>Set Time:</strong> {__('general.enter_hours_minutes_and_seconds_for_each')}</li>
                                <li><strong>Controls:</strong> {__('general.start_pause_or_reset_each_timer_individu')}</li>
                                <li><strong>Alarm:</strong> {__('general.an_audio_alarm_will_sound_when_a_timer_r')}</li>
                            </ul>
                        </CardContent>
                    </Card>
                </div>
            </div>
        </WebToolsLayout>
    );
}
